        results.push(result);
    }
    Ok(Response::new(UpdateBatchResponse { result: results... }))

// The critical issue: operations are executed sequentially in a for loop
// Each operation is applied immediately to the database
// If a later operation fails, earlier operations are NOT rolled back
// The `} ?;` at line 682 only stops further execution on error
